package network.conet.chat.passcode

import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The callId format: 8 to 128 characters of [A-Za-z0-9_-], generated by the calling client. The boundaries are
 * 7 and 8 at the bottom, 128 and 129 at the top. A malformed callId is refused by [IncomingCallRegistry.incomingCallBind] and, in the unlock
 * entry, answered as a call mismatch (bad_request before the table takes effect, call_mismatch after).
 */
class CallIdFormatTest {
    private val eoa = "0x39581c72b8c7d0de85ff22cf3ae178ae813957aa"

    private fun repeat(n: Int) = "a".repeat(n)

    @Test
    fun theLengthBoundariesAreSevenInvalidEightValidOneTwentyEightValidOneTwentyNineInvalid() {
        assertFalse(PasscodeUnlockEntry.isCallId(repeat(7)))
        assertTrue(PasscodeUnlockEntry.isCallId(repeat(8)))
        assertTrue(PasscodeUnlockEntry.isCallId(repeat(128)))
        assertFalse(PasscodeUnlockEntry.isCallId(repeat(129)))
    }

    @Test
    fun theAllowedCharactersAreLettersDigitsUnderscoreAndHyphen() {
        assertTrue(PasscodeUnlockEntry.isCallId("Aa0_-zZ9x"))
        assertFalse(PasscodeUnlockEntry.isCallId("call.id.12"))
        assertFalse(PasscodeUnlockEntry.isCallId("call:id:12"))
        assertFalse(PasscodeUnlockEntry.isCallId("call id 12"))
        assertFalse(PasscodeUnlockEntry.isCallId("call/id/12"))
        assertFalse(PasscodeUnlockEntry.isCallId(""))
    }

    @Test
    fun aThirtyTwoCharacterLowerHexIdIsValid() {
        // The current generation: 32 lower-case hex characters.
        assertTrue(PasscodeUnlockEntry.isCallId("0123456789abcdef0123456789abcdef"))
    }

    @Test
    fun bindRefusesASevenCharacterIdAndAcceptsAnEightCharacterOne() {
        val calls = IncomingCallRegistry(SessionGeneration())
        assertFalse("7 characters is refused", calls.incomingCallBind(repeat(7), eoa))
        assertTrue("the refused bind registered nothing", calls.check(repeat(7), eoa, eoa) is IncomingCallRegistry.CallCheck.CallMismatch)
        assertTrue("8 characters is accepted", calls.incomingCallBind(repeat(8), eoa))
        assertTrue(calls.check(repeat(8), eoa, eoa) is IncomingCallRegistry.CallCheck.Proceed)
    }

    @Test
    fun bindRefusesA129CharacterIdAndAccepts128() {
        val calls = IncomingCallRegistry(SessionGeneration())
        assertFalse(calls.incomingCallBind(repeat(129), eoa))
        assertTrue(calls.incomingCallBind(repeat(128), eoa))
    }

    @Test
    fun aMalformedCallIdInTheUnlockRequestIsBadRequestBeforeTheTableAndCallMismatchAfter() {
        val calls = IncomingCallRegistry(SessionGeneration())
        calls.incomingCallBind(repeat(8), eoa)
        for (bad in listOf(repeat(7), repeat(129), "bad id!!")) {
            val req = JSONObject().put("eoa", eoa).put("passcode", "12345678").put("callId", bad)
            val before = PasscodeUnlockEntry.admit(req, eoa, calls, callTableInEffect = false) as PasscodeUnlockEntry.Admission.Refused
            assertEquals("bad_request", before.code)
            assertFalse(before.endsCall)
            val after = PasscodeUnlockEntry.admit(req, eoa, calls, callTableInEffect = true) as PasscodeUnlockEntry.Admission.Refused
            assertEquals("call_mismatch", after.code)
            assertFalse(after.endsCall)
        }
    }

    @Test
    fun aValidRegisteredIdPassesTheUnlockEntry() {
        val calls = IncomingCallRegistry(SessionGeneration())
        calls.incomingCallBind(repeat(8), eoa)
        val req = JSONObject().put("eoa", eoa).put("passcode", "12345678").put("callId", repeat(8))
        assertTrue(PasscodeUnlockEntry.admit(req, eoa, calls) is PasscodeUnlockEntry.Admission.Pass)
    }
}
